    def values(tag,seen=()):
        out=set()
        for item in tags[tag]:
            item=item['id'] if isinstance(item,dict) else item
            if item.startswith('#minecraft:'):
                sub=item.split(':',1)[1]
                if sub not in seen:out.update(values(sub,seen+(tag,)))
